package io.github.diodeme.ji.security.oauth;

import io.github.diodeme.ji.security.secret.SecretValue;
import java.time.Instant;
import java.util.Objects;
import java.util.Optional;

/** Host-internal token result. Secret fields are scoped and never serializable. */
public final class OAuthTokenSet implements AutoCloseable {
    private final SecretValue accessToken;
    private final Optional<SecretValue> refreshToken;
    private final String tokenType;
    private final Optional<Instant> expiresAt;

    public OAuthTokenSet(SecretValue accessToken, Optional<SecretValue> refreshToken, String tokenType,
            Optional<Instant> expiresAt) {
        this.accessToken = [REDACTED_CREDENTIAL] "accessToken");
        this.refreshToken = [REDACTED_CREDENTIAL] =[REDACTED_CREDENTIAL] null ? Optional.empty() : refreshToken;
        if (tokenType == null || tokenType.isBlank()) throw new IllegalArgumentException("tokenType must not be blank");
        this.tokenType = tokenType;
        this.expiresAt = expiresAt == null ? Optional.empty() : expiresAt;
    }

    public SecretValue accessToken() {
        return accessToken;
    }

    public Optional<SecretValue> refreshToken() {
        return refreshToken;
    }

    public String tokenType() {
        return tokenType;
    }

    public Optional<Instant> expiresAt() {
        return expiresAt;
    }

    @Override
    public void close() {
        accessToken.close();
        refreshToken.ifPresent(SecretValue::close);
    }

    @Override
    public String toString() {
        return "OAuthTokenSet[accessToken=[REDACTED_CREDENTIAL] refreshToken="
                + (refreshToken.isPresent() ? "REDACTED" : "ABSENT") + ", tokenType=" + tokenType
                + ", expiresAt=" + expiresAt + "]";
    }
}
